121	type RightPanel = PanelId;
122	
123	/** Widest the right panel may be while keeping the manuscript usable. */
124	const MIN_EDITOR_WIDTH = 360;
125	const LEFT_SIDEBAR_WIDTH = 288;
126	
127	/**
128	 * Below this the rails stop being furniture and start being the whole screen,
129	 * so they are undocked rather than squeezed. Matches Tailwind's `sm`, which is
130	 * where the toolbar also switches to a single scrolling row.
131	 */
132	const NARROW_VIEWPORT = 640;
133	
134	function maxRightPanelWidth(leftSidebarOpen: boolean): number {
135	  const reserved =
136	    (leftSidebarOpen ? LEFT_SIDEBAR_WIDTH : 0) + MIN_EDITOR_WIDTH;
137	  // The 260px floor is a minimum *useful* panel, not a promise there is room
138	  // for one: on a 390px phone it left the manuscript 122px wide. Callers must
139	  // check `fitsDockedPanel` before docking rather than trusting this number.
140	  return Math.max(260, Math.min(560, window.innerWidth - reserved));
141	}
142	
143	/** Is there room to dock a rail without crushing the manuscript? */
144	function fitsDockedPanel(leftSidebarOpen: boolean): boolean {
145	  if (window.innerWidth < NARROW_VIEWPORT) return false;
146	  const reserved =
147	    (leftSidebarOpen ? LEFT_SIDEBAR_WIDTH : 0) + MIN_EDITOR_WIDTH;
148	  return window.innerWidth - reserved >= 260;
149	}
