151	interface LayoutStore {
152	  rightPanel: RightPanel;
153	  leftSidebarOpen: boolean;
154	  rightPanelOpen: boolean;
155	  /** Panel state to restore when zen mode is turned back off. Null when not in zen mode. */
156	  panelsBeforeZen: { left: boolean; right: boolean } | null;
157	  /** True while zen mode is active — drives masthead/toolbar hiding. */
158	  zenActive: boolean;
159	  hydrated: boolean;
160	  brief: ProjectBrief | null;
161	  modelBrief: ProjectBrief | null;
162	  modelBriefFolioId: string | null;
163	  briefEditions: BriefEdition[];
164	  editorSeed: string;
165	  folios: Folio[];
166	  activeFolioId: string | null;
167	  folioKey: number;
168	  rightPanelWidth: number;
169	  // Inline form states (replace native prompts/confirms)
170	  newFolioFormOpen: boolean;
171	  confirmNukeOpen: boolean;
172	  /** Whether the "you're working locally" sign-in nudge has been dismissed. */
173	  signInToastDismissed: boolean;
174	  /** When set, the editor joins a multiplayer session. */
175	  sharedLixId: string | null;
176	  /** Server-authoritative role for the active shared document. */
177	  sharedRole: "owner" | "editor" | "commenter" | null;
178	  /** True while joining a shared document is in progress. */
179	  joiningShared: boolean;
180	  /** Structured error if joining failed. */
181	  joinError: AppError | null;
182	  /** Structured error if the local workspace could not be opened. */
183	  workspaceError: AppError | null;
184	  /** Unread counts per board tab, so passive work is never silent. */
185	  activity: ActivityCounts;
186	}
