188	/* ────────────────────────────────────────────────────────────────
189	 *  Editorial dateline lives in utils/editorial-format.ts so the landing
190	 *  preview renders the same masthead line. Folio numerals too.
191	 * ──────────────────────────────────────────────────────────────── */
