193	/**
194	 * The writer's room — the full editorial desk: the Drawer of folios on
195	 * the left, the manuscript in the centre, and the Editorial Board (Cast,
196	 * Rubric, Marginalia, Apparatus, Versions) on the right. The Apparatus runs research
197	 * agents in the background, debounced on the draft.
198	 *
199	 * First-run onboarding lives at /dossier/create; dossier refinement at
200	 * /dossier/refine. This route owns the workspace and migrates the legacy
201	 * single-draft key into Folio I on first load.
202	 */
203	export default component$(() => {
204	  const nav = useNavigate();
205	  const location = useLocation();
206	  const clientSig = useConvexClient();
207	  const auth = useAuth();
208	  // House sync uses browser storage and the authenticated client lifecycle.
209	  // eslint-disable-next-line qwik/no-use-visible-task
210	  useVisibleTask$(({ track, cleanup }) => {
211	    track(() => clientSig.value);
212	    track(() => auth.value);
213	    if (!hasAuthenticatedConvexIdentity(auth.value)) return;
214	    cleanup(
215	      startHouseSync(
216	        () =>
217	          hasAuthenticatedConvexIdentity(auth.value)
218	            ? (clientSig.value ?? null)
219	            : null,
220	        auth.value.user!.id,
221	      ),
222	    );
223	  });
224	  // Controls the shared AccountMenu (Editor's Office); external triggers such
225	  // as the ?auth=1 deep link and the local-only nudge flip this open.
226	  const accountOpen = useSignal(false);
227	  const manuscriptEditor = useSignal<NoSerialize<Editor>>();
228	  const sharedOpenGeneration = useSignal(0);
229	  const opensVersionHistory =
230	    location.url.searchParams.get("panel") === "history";
231	  const store = useStore<LayoutStore>({
232	    rightPanel: opensVersionHistory ? "history" : "personas",
233	    leftSidebarOpen: false,
234	    // Begin with the manuscript, not the entire editorial apparatus. The
235	    // board remains one click away and retains its unread badges.
236	    rightPanelOpen: opensVersionHistory,
237	    panelsBeforeZen: null,
238	    zenActive: !opensVersionHistory,
239	    hydrated: false,
240	    brief: null,
241	    modelBrief: null,
242	    modelBriefFolioId: null,
243	    briefEditions: [],
244	    editorSeed: "",
245	    folios: [],
246	    activeFolioId: null,
247	    folioKey: 0,
248	    rightPanelWidth: 340,
249	    newFolioFormOpen: false,
250	    confirmNukeOpen: false,
251	    // Default true to avoid a flash before the meta flag loads.
252	    signInToastDismissed: true,
253	    sharedLixId: null,
254	    sharedRole: null,
255	    joiningShared: false,
256	    joinError: null,
257	    workspaceError: null,
258	    activity: panelActivity(),
259	  });
260	
261	  // eslint-disable-next-line qwik/no-use-visible-task
262	  useVisibleTask$(({ cleanup }) => {
263	    const lastWordCounts = new Map<string, number>();
264	    const editedFolios = new Set<string>();
265	
266	    (async () => {
267	      try {
268	        const legacyBrief = loadProjectBrief();
269	        const folios = await loadFoliosFromIdb();
270	        const activeFolioId = await loadActiveFolioIdFromIdb();
271	        const requestedSharedId = new URLSearchParams(
272	          window.location.search,
273	        ).get("shared");
274	
275	        // No dossier yet → the writer belongs in onboarding first.
276	        if (!legacyBrief && folios.length === 0 && !requestedSharedId) {
277	          void nav("/dossier/create/");
278	          return;
279	        }
280	
281	        // Migration: old storage had a single draft. If we have a brief but no
282	        // folios, create a Folio I from the legacy draft key.
283	        if (legacyBrief && folios.length === 0) {
284	          const legacyDraft = loadLegacyDraftHtml();
285	          const draftFolio: Folio = {
286	            id: crypto.randomUUID(),
287	            name: legacyBrief.answers.workingTitle || "Current draft",
288	            type: "draft",
289	            createdAt: legacyBrief.completedAt,
290	            updatedAt: Date.now(),
291	          };
292	          await saveFoliosToIdb([draftFolio]);
293	          await saveFolioContentToIdb(draftFolio.id, legacyDraft);
294	          await saveActiveFolioIdToIdb(draftFolio.id);
295	          store.folios = [draftFolio];
296	          store.activeFolioId = draftFolio.id;
297	          store.editorSeed = legacyDraft;
298	          await saveProjectBriefForFolio(draftFolio.id, legacyBrief);
299	          markDirty();
300	        } else if (folios.length > 0) {
301	          store.folios = folios;
302	          store.activeFolioId = activeFolioId ?? folios[0].id;
303	          if (await recoverFolioContentFromCrashMirror(store.activeFolioId)) {
304	            markDirty(["folioContent"], store.activeFolioId);
305	          }
306	          store.editorSeed = await loadFolioContentFromIdb(store.activeFolioId);
307	        }
308	
309	        store.brief = await loadProjectBriefForFolio(store.activeFolioId);
310	        if (store.activeFolioId) {
311	          await migrateLegacyEditorialArtifacts(
312	            store.activeFolioId,
313	            canClaimLegacyEditorialArtifacts(
314	              store.folios.map((folio) => folio.id),
315	              store.activeFolioId,
316	            ),
317	          );
318	        }
319	        const folioDossiers = await loadAllBriefsFromIdb();
320	        if (
321	          !store.brief &&
322	          folioDossiers.length === 0 &&
323	          legacyBrief &&
324	          store.activeFolioId
325	        ) {
326	          await saveProjectBriefForFolio(store.activeFolioId, legacyBrief);
327	          store.brief = legacyBrief;
328	        }
329	        store.briefEditions = await loadBriefEditions(store.activeFolioId);
330	        store.hydrated = true;
331	
332	        const openedFolio = store.folios.find(
333	          (folio) => folio.id === store.activeFolioId,
334	        );
335	        if (openedFolio) {
336	          lastWordCounts.set(openedFolio.id, countDraftWords(store.editorSeed));
337	          void captureProductEvent("folio_opened", {
338	            source: "editor",
339	            folio_type: openedFolio.type,
340	          });
341	        }
342	
343	        // Surface the local-only sign-in nudge unless it was dismissed before.
344	        const dismissed = await loadMetaFromIdb<boolean>(
345	          "signin-toast-dismissed",
346	        );
347	        store.signInToastDismissed = dismissed === true;
348	
349	        // Arriving from the landing "Sign in" link → open the auth panel.
350	        if (new URLSearchParams(window.location.search).get("auth") === "1") {
351	          accountOpen.value = true;
352	        }
353	      } catch (err) {
354	        reportApplicationDiagnostic("twyne:editor:open-workspace", err, {
355	          operation: "open-workspace",
356	        });
357	        store.workspaceError = normalizeApplicationError(err, {
358	          source: "application",
359	          metadata: { operation: "open-workspace" },
360	        });
361	        store.hydrated = true;
362	      }
363	    })();
364	
365	    // ── Coalesced local persistence ────────────────────────────────────
366	    // `twyne:content` already arrives coalesced from the editor, so this only
367	    // needs to absorb bursts from non-typing sources (folio metadata edits)
368	    // and to force a flush when the tab is hidden so a quick close never
369	    // drops the tail.
370	    //
371	    // Only lifecycle departures write the synchronous crash mirror.
372	    // Folio-scoped IndexedDB remains the store of record during typing.
373	    const LOCAL_PERSIST_DEBOUNCE_MS = 400;
374	    let localPersistTimer: number | null = null;
375	    let pendingDraftHtml: string | null = null;
376	    let pendingDraftFolioId: string | null = null;
377	    let folioArrayDirty = false;
378	    let pageLeaving = false;
379	    const unacknowledgedDrafts = new Map<string, string>();
380	
381	    const flushLocalPersist = (leaving = false) => {
382	      localPersistTimer = null;
383	      // A timer may already have started the IDB write and cleared pending.
384	      // Keep that draft recoverable until its own acknowledgement arrives.
385	      if (leaving) {
386	        for (const [folioId, html] of unacknowledgedDrafts) {
387	          if (folioId === store.activeFolioId) continue;
388	          writeCrashMirror(folioId, html);
389	        }
390	        // The legacy emergency slot contains one folio. A save from a folio
391	        // opened earlier must never displace the manuscript being left now.
392	        const activeHtml =
393	          store.activeFolioId && unacknowledgedDrafts.get(store.activeFolioId);
394	        if (
395	          store.activeFolioId &&
396	          activeHtml !== undefined &&
397	          activeHtml !== null
398	        ) {
399	          writeCrashMirror(store.activeFolioId, activeHtml);
400	        }
401	      }
402	      if (pendingDraftHtml !== null && pendingDraftFolioId !== null) {
403	        const [html, folioId] = [pendingDraftHtml, pendingDraftFolioId];
404	        pendingDraftHtml = null;
405	        pendingDraftFolioId = null;
406	        // On the way out the IndexedDB write may not get to commit, so leave a
407	        // synchronous copy behind first. During normal typing this is skipped.
408	        void saveFolioContentToIdb(folioId, html)
409	          .then(() => {
410	            if (unacknowledgedDrafts.get(folioId) === html) {
411	              unacknowledgedDrafts.delete(folioId);
412	            }
413	            clearCrashMirror(folioId, html);
414	            void usageLedger
415	              .recordWritingActivity({ folioId })
416	              .catch(() => undefined);
417	            void createRevisionSnapshot({
418	              folioId,
419	              html,
420	              source: "automatic",
421	            });
422	            // "Saved Xs ago" means on disk, so stamp it only once IDB commits.
423	            window.dispatchEvent(
424	              new CustomEvent("twyne:draft-saved", { detail: { folioId } }),
425	            );
426	          })
427	          .catch((error) =>
428	            reportApplicationDiagnostic("twyne:editor:save-draft", error, {
429	              operation: "save-draft",
430	            }),
431	          );
432	      }
433	      if (folioArrayDirty) {
434	        folioArrayDirty = false;
435	        void saveFoliosToIdb(store.folios);
436	      }
437	    };
438	
439	    const scheduleLocalPersist = () => {
440	      if (localPersistTimer !== null) return;
441	      localPersistTimer = window.setTimeout(
442	        flushLocalPersist,
443	        LOCAL_PERSIST_DEBOUNCE_MS,
444	      );
445	    };
446	
447	    const flushLocalPersistNow = (leaving = false) => {
448	      if (localPersistTimer !== null) {
449	        window.clearTimeout(localPersistTimer);
450	        localPersistTimer = null;
451	      }
452	      flushLocalPersist(leaving);
453	    };
454	
455	    const cancelStaleVisualSave = (event: Event) => {
456	      const { folioId } = (event as CustomEvent<{ folioId: string }>).detail;
457	      unacknowledgedDrafts.delete(folioId);
458	      clearCrashMirror(folioId);
459	      if (pendingDraftFolioId !== folioId) return;
460	      if (localPersistTimer !== null) window.clearTimeout(localPersistTimer);
461	      localPersistTimer = null;
462	      pendingDraftHtml = null;
463	      pendingDraftFolioId = null;
464	    };
465	    const sourceCommitted = (event: Event) => {
466	      const { folioId } = (event as CustomEvent<{ folioId: string }>).detail;
467	      markDirty(["folioContent"], folioId);
468	    };
469	    window.addEventListener("twyne:typst-applying", cancelStaleVisualSave);
470	    window.addEventListener("twyne:typst-source-committed", sourceCommitted);
471	    const remoteSaved = (event: Event) => {
472	      if (
473	        (event as CustomEvent<FolioContentSavedDetail>).detail.origin ===
474	        "remote"
475	      ) {
476	        cancelStaleVisualSave(event);
477	      }
478	    };
479	    window.addEventListener(FOLIO_CONTENT_SAVED, remoteSaved);
480	    cleanup(() => {
481	      window.removeEventListener("twyne:typst-applying", cancelStaleVisualSave);
482	      window.removeEventListener(FOLIO_CONTENT_SAVED, remoteSaved);
483	      window.removeEventListener(
484	        "twyne:typst-source-committed",
485	        sourceCommitted,
486	      );
487	    });
488	
489	    const onLocalPersistPageHide = () => {
490	      // pagehide can precede visibilitychange during a same-tab navigation.
491	      // Keep departure explicit so a later editor listener cannot schedule a
492	      // new debounce after this route listener has already flushed.
493	      pageLeaving = true;
494	      flushLocalPersistNow(true);
495	    };
496	    const onLocalPersistPageShow = () => {
497	      pageLeaving = false;
498	    };
499	    const onLocalPersistVisibility = () => {
500	      if (document.visibilityState === "hidden") flushLocalPersistNow(true);

500	      if (document.visibilityState === "hidden") flushLocalPersistNow(true);
501	    };
502	
503	    // ── Save editor content to the active folio ──
504	    const contentHandler = (e: Event) => {
505	      const { html, wordCount: currentWordCount } = (
506	        e as CustomEvent<DraftContentDetail>
507	      ).detail;
508	      if (store.activeFolioId) {
509	        const folioId = store.activeFolioId;
510	        const previousWordCount =
511	          lastWordCounts.get(folioId) ?? currentWordCount;
512	
513	        if (!editedFolios.has(folioId)) {
514	          editedFolios.add(folioId);
515	          void captureProductEvent("draft_milestone_reached", {
516	            milestone: "first_edit",
517	            word_count_bucket: wordCountBucket(currentWordCount),
518	          });
519	        }
520	        for (const milestone of crossedDraftMilestones(
521	          previousWordCount,
522	          currentWordCount,
523	        )) {
524	          if (milestone === "first_edit") continue;
525	          void captureProductEvent("draft_milestone_reached", {
526	            milestone,
527	            word_count_bucket: wordCountBucket(currentWordCount),
528	          });
529	        }
530	        lastWordCounts.set(folioId, currentWordCount);
531	
532	        const idx = store.folios.findIndex((f) => f.id === folioId);
533	        if (idx >= 0) {
534	          store.folios[idx].updatedAt = Date.now();
535	          folioArrayDirty = true;
536	        }
537	        pendingDraftHtml = html;
538	        pendingDraftFolioId = folioId;
539	        unacknowledgedDrafts.set(folioId, html);
540	        // When the editor flushes its derive because the page is going away,
541	        // there is no later tick to coalesce into — write it out now.
542	        if (pageLeaving || document.visibilityState === "hidden") {
543	          flushLocalPersistNow(true);
544	        } else {
545	          scheduleLocalPersist();
546	        }
547	        markDirty(["folioContent", "folios"], folioId);
548	      }
549	    };
550	    window.addEventListener("twyne:content", contentHandler);
551	    cleanup(() => window.removeEventListener("twyne:content", contentHandler));
552	
553	    // A hidden tab is a reliable cue that the writer is leaving — flush the
554	    // pending draft synchronously instead of waiting on the coalesce window.
555	    window.addEventListener("pagehide", onLocalPersistPageHide);
556	    window.addEventListener("pageshow", onLocalPersistPageShow);
557	    document.addEventListener("visibilitychange", onLocalPersistVisibility);
558	    cleanup(() => {
559	      window.removeEventListener("pagehide", onLocalPersistPageHide);
560	      window.removeEventListener("pageshow", onLocalPersistPageShow);
561	      document.removeEventListener(
562	        "visibilitychange",
563	        onLocalPersistVisibility,
564	      );
565	      if (localPersistTimer !== null) {
566	        window.clearTimeout(localPersistTimer);
567	        localPersistTimer = null;
568	      }
569	    });
570	
571	    const loadFolioHandler = (e: Event) => {
572	      if (!store.activeFolioId) return;
573	      const html = (e as CustomEvent).detail as string;
574	      lastWordCounts.set(store.activeFolioId, countDraftWords(html));
575	    };
576	    window.addEventListener("twyne:load-folio", loadFolioHandler);
577	    cleanup(() =>
578	      window.removeEventListener("twyne:load-folio", loadFolioHandler),
579	    );
580	
